final class KuranMetni {
    private KuranMetni() {}

    /** Fâtiha Sûresi (1) */
    static final String FATIHA_AR = "بِسۡمِ ٱللَّهِ ٱلرَّحۡمَٰنِ ٱلرَّحِيمِ (١)\nٱلۡحَمۡدُ لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ (٢)\nٱلرَّحۡمَٰنِ ٱلرَّحِيمِ (٣)\nمَٰلِكِ يَوۡمِ ٱلدِّينِ (٤)\nإِيَّاكَ نَعۡبُدُ وَإِيَّاكَ نَسۡتَعِينُ (٥)\nٱهۡدِنَا ٱلصِّرَٰطَ ٱلۡمُسۡتَقِيمَ (٦)\nصِرَٰطَ ٱلَّذِينَ أَنۡعَمۡتَ عَلَيۡهِمۡ غَيۡرِ ٱلۡمَغۡضُوبِ عَلَيۡهِمۡ وَلَا ٱلضَّآلِّينَ (٧)";
    static final String FATIHA_MEAL = "Rahman ve Rahim olan Allah'ın adıyla. Hamd, Alemlerin Rabbi Allah'a mahsustur. O Rahman ve Rahim'dir. Din Gününün sahibidir. Ancak Sana kulluk eder ve yalnız Senden yardım dileriz. Bizi doğru yola eriştir. Nimete erdirdiğin kimselerin yoluna; gazaba uğrayanların, ya da sapıtanların yoluna değil.";

    /** Fîl Sûresi (105) */
    static final String FIL_AR = "أَلَمۡ تَرَ كَيۡفَ فَعَلَ رَبُّكَ بِأَصۡحَٰبِ ٱلۡفِيلِ (١)\nأَلَمۡ يَجۡعَلۡ كَيۡدَهُمۡ فِي تَضۡلِيلٖ (٢)\nوَأَرۡسَلَ عَلَيۡهِمۡ طَيۡرًا أَبَابِيلَ (٣)\nتَرۡمِيهِم بِحِجَارَةٖ مِّن سِجِّيلٖ (٤)\nفَجَعَلَهُمۡ كَعَصۡفٖ مَّأۡكُولِۭ (٥)";
    static final String FIL_MEAL = "Fil sahiplerine Rabbinin ne ettiğini görmedin mi? Onların düzenlerini boşa çıkarmadı mı? Onların üzerine, sert taşlar atan sürülerle kuşlar gönderdi. Sonunda onları, yenilmiş ekin gibi yaptı.";

    /** Kureyş Sûresi (106) */
    static final String KUREYS_AR = "لِإِيلَٰفِ قُرَيۡشٍ (١)\nإِۦلَٰفِهِمۡ رِحۡلَةَ ٱلشِّتَآءِ وَٱلصَّيۡفِ (٢)\nفَلۡيَعۡبُدُواْ رَبَّ هَٰذَا ٱلۡبَيۡتِ (٣)\nٱلَّذِيٓ أَطۡعَمَهُم مِّن جُوعٖ وَءَامَنَهُم مِّنۡ خَوۡفِۭ (٤)";
    static final String KUREYS_MEAL = "Kureyş kabilesinin yaz ve kış yolculuklarında uzlaşması ve anlaşması sağlanmıştır. Öyleyse kendilerini açken doyuran ve korku içindeyken güven veren bu Ev'in (Kabe'nin) Rabbine kulluk etsinler.";

    /** Maûn Sûresi (107) */
    static final String MAUN_AR = "أَرَءَيۡتَ ٱلَّذِي يُكَذِّبُ بِٱلدِّينِ (١)\nفَذَٰلِكَ ٱلَّذِي يَدُعُّ ٱلۡيَتِيمَ (٢)\nوَلَا يَحُضُّ عَلَىٰ طَعَامِ ٱلۡمِسۡكِينِ (٣)\nفَوَيۡلٞ لِّلۡمُصَلِّينَ (٤)\nٱلَّذِينَ هُمۡ عَن صَلَاتِهِمۡ سَاهُونَ (٥)\nٱلَّذِينَ هُمۡ يُرَآءُونَ (٦)\nوَيَمۡنَعُونَ ٱلۡمَاعُونَ (٧)";
    static final String MAUN_MEAL = "Dini yalan sayanı gördün mü? Öksüzü kakıştıran, yoksulu doyurmaya yanaşmayan kimse işte odur. Vay o namaz kılanların haline ki. Onlar kıldıkları namazdan gafildirler. Onlar gösteriş yaparlar. Onlar basit şeyleri dahi vermezler.";

    /** Kevser Sûresi (108) */
    static final String KEVSER_AR = "إِنَّآ أَعۡطَيۡنَٰكَ ٱلۡكَوۡثَرَ (١)\nفَصَلِّ لِرَبِّكَ وَٱنۡحَرۡ (٢)\nإِنَّ شَانِئَكَ هُوَ ٱلۡأَبۡتَرُ (٣)";
    static final String KEVSER_MEAL = "Doğrusu sana pek çok nimet vermişizdir. Öyleyse Rabbin için namaz kıl, kurban kes. Doğrusu adı sanı ortadan kalkacak olan, sana kin tutan kimsedir.";

    /** Kâfirûn Sûresi (109) */
    static final String KAFIRUN_AR = "قُلۡ يَـٰٓأَيُّهَا ٱلۡكَٰفِرُونَ (١)\nلَآ أَعۡبُدُ مَا تَعۡبُدُونَ (٢)\nوَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ (٣)\nوَلَآ أَنَا۠ عَابِدٞ مَّا عَبَدتُّمۡ (٤)\nوَلَآ أَنتُمۡ عَٰبِدُونَ مَآ أَعۡبُدُ (٥)\nلَكُمۡ دِينُكُمۡ وَلِيَ دِينِ (٦)";
    static final String KAFIRUN_MEAL = "De ki: \"Ey inkarcılar. Ben sizin taptıklarınıza tapmam. Benim taptığıma da sizler tapmazsınız. Ben de sizin taptığınıza tapacak değilim. Benim taptığıma da sizler tapmıyorsunuz. Sizin dininiz size, benim dinim banadır.\"";

    /** Nasr Sûresi (110) */
    static final String NASR_AR = "إِذَا جَآءَ نَصۡرُ ٱللَّهِ وَٱلۡفَتۡحُ (١)\nوَرَأَيۡتَ ٱلنَّاسَ يَدۡخُلُونَ فِي دِينِ ٱللَّهِ أَفۡوَاجٗا (٢)\nفَسَبِّحۡ بِحَمۡدِ رَبِّكَ وَٱسۡتَغۡفِرۡهُۚ إِنَّهُۥ كَانَ تَوَّابَۢا (٣)";
    static final String NASR_MEAL = "Allah'ın yardımı ve zafer günü gelip, insanların Allah'ın dinine akın akın girdiklerini görünce, Rabbini överek tesbih et; O'ndan bağışlama dile, çünkü O, tevbeleri daima kabul edendir.";

    /** Tebbet Sûresi (111) */
    static final String TEBBET_AR = "تَبَّتۡ يَدَآ أَبِي لَهَبٖ وَتَبَّ (١)\nمَآ أَغۡنَىٰ عَنۡهُ مَالُهُۥ وَمَا كَسَبَ (٢)\nسَيَصۡلَىٰ نَارٗا ذَاتَ لَهَبٖ (٣)\nوَٱمۡرَأَتُهُۥ حَمَّالَةَ ٱلۡحَطَبِ (٤)\nفِي جِيدِهَا حَبۡلٞ مِّن مَّسَدِۭ (٥)";
    static final String TEBBET_MEAL = "Ebu Leheb'in elleri kurusun; kurudu da. Malı ve kazandığı kendisine fayda vermedi. Alevli ateşe yaslanacaktır. Karısı da, boynunda bir ip olduğu halde ona odun taşıyacaktır.";

    /** İhlâs Sûresi (112) */
    static final String IHLAS_AR = "قُلۡ هُوَ ٱللَّهُ أَحَدٌ (١)\nٱللَّهُ ٱلصَّمَدُ (٢)\nلَمۡ يَلِدۡ وَلَمۡ يُولَدۡ (٣)\nوَلَمۡ يَكُن لَّهُۥ كُفُوًا أَحَدُۢ (٤)";
    static final String IHLAS_MEAL = "De ki: O Allah bir tektir. Allah her şeyden müstağni ve her şey O'na muhtaçtır. O doğurmamış ve doğmamıştır. Hiçbir şey O'na denk değildir.";

    /** Felak Sûresi (113) */
    static final String FELAK_AR = "قُلۡ أَعُوذُ بِرَبِّ ٱلۡفَلَقِ (١)\nمِن شَرِّ مَا خَلَقَ (٢)\nوَمِن شَرِّ غَاسِقٍ إِذَا وَقَبَ (٣)\nوَمِن شَرِّ ٱلنَّفَّـٰثَٰتِ فِي ٱلۡعُقَدِ (٤)\nوَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ (٥)";
    static final String FELAK_MEAL = "De ki: \"Yaratıkların şerrinden, bastırdığı zaman karanlığın şerrinden, düğümlere nefes eden büyücülerin şerrinden, hased ettiği zaman hasedcilerin şerrinden, tan yerini ağartan Rabbe sığınırım.\"";

    /** Nâs Sûresi (114) */
    static final String NAS_AR = "قُلۡ أَعُوذُ بِرَبِّ ٱلنَّاسِ (١)\nمَلِكِ ٱلنَّاسِ (٢)\nإِلَٰهِ ٱلنَّاسِ (٣)\nمِن شَرِّ ٱلۡوَسۡوَاسِ ٱلۡخَنَّاسِ (٤)\nٱلَّذِي يُوَسۡوِسُ فِي صُدُورِ ٱلنَّاسِ (٥)\nمِنَ ٱلۡجِنَّةِ وَٱلنَّاسِ (٦)";
    static final String NAS_MEAL = "De ki: \"İnsanlardan ve cinlerden ve insanların gönüllerine vesvese veren o sinsi vesvesecinin şerrinden, insanların Tanrısı, insanların Hükümranı ve insanların Rabbi olan Allah'a sığınırım.\"";

    /** Bakara 2:201 ayetinin dua kısmı */
    static final String RABBENA_ATINA_AR = "رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ";

    /** İbrâhîm 14:41 */
    static final String RABBENAGFIRLI_AR = "رَبَّنَا ٱغۡفِرۡ لِي وَلِوَٰلِدَيَّ وَلِلۡمُؤۡمِنِينَ يَوۡمَ يَقُومُ ٱلۡحِسَابُ";
    static final String RABBENAGFIRLI_MEAL = "Rabbimiz! Hesap görülecek günde, beni, anamı babamı ve inananları bağışla.";

    /** Bakara 2:255 (Âyetü'l-Kürsî) */
    static final String AYETEL_KURSI_AR = "ٱللَّهُ لَآ إِلَٰهَ إِلَّا هُوَ ٱلۡحَيُّ ٱلۡقَيُّومُۚ لَا تَأۡخُذُهُۥ سِنَةٞ وَلَا نَوۡمٞۚ لَّهُۥ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ مَن ذَا ٱلَّذِي يَشۡفَعُ عِندَهُۥٓ إِلَّا بِإِذۡنِهِۦۚ يَعۡلَمُ مَا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡۖ وَلَا يُحِيطُونَ بِشَيۡءٖ مِّنۡ عِلۡمِهِۦٓ إِلَّا بِمَا شَآءَۚ وَسِعَ كُرۡسِيُّهُ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَۖ وَلَا يَـُٔودُهُۥ حِفۡظُهُمَاۚ وَهُوَ ٱلۡعَلِيُّ ٱلۡعَظِيمُ";
    static final String AYETEL_KURSI_MEAL = "Allah, O'ndan başka tanrı olmayan, kendisini uyuklama ve uyku tutmayan, diri, her an yaratıklarını gözetip durandır. Göklerde olan ve yerde olan ancak O'nundur. O'nun izni olmadan katında şefaat edecek kimdir? Onların işlediklerini ve işleyeceklerini bilir, dilediğinden başka ilminden hiçbir şeyi kavrayamazlar. Hükümranlığı gökleri ve yeri kaplamıştır, onların gözetilmesi O'na ağır gelmez. O yücedir, büyüktür.";
}
